# Find non-zero objects by connected components
class UnionFind:
    def __init__(self, n, m):
        self.parent = list(range(n * m))
    def find(self, i):
        if self.parent[i] != i:
            self.parent[i] = self.find(self.parent[i])
        return self.parent[i]
    def union(self, i, j):
        pi, pj = self.find(i), self.find(j)
        if pi != pj:
            self.parent[pj] = pi

def get_components(grid):
    n, m = len(grid), len(grid[0])
    uf = UnionFind(n, m)
    directions = [(0, 1), (1, 0)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                continue
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] != 0:
                    r1, c1 = i * m + j
                    r2, c2 = ni * m + nj
                    uf.union(r1, r2)

    # Group by root
    groups = {}
    for i in range(n):
        for j in range(m):
            if grid[i][j] != 0:
                root = uf.find(i * m + j)
                if root not in groups:
                    groups[root] = []
                groups[root].append((i, j))

    return list(groups.values())

