def extract_component_patterns(grid):
    """Extract the 7-wide component pattern centered on the 4-6-4 vertical bar"""
    n, m = len(grid), len(grid[0])
    components = {}

    # Find connected components of non-zero
    visited = [[False]*m for _ in range(n)]

    def get_component_start(grid):
        # Find the first non-zero
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] != 0 and not visited[r][c]:
                    return (r, c)
        return None

    for r in range(n):
        for c in range(m):
            if grid[r][c] != 0 and not visited[r][c]:
                # BFS to get connected cells
                cells = [(r, c)]
                visited[r][c] = True
                q = [(r, c)]
                while q:
                    curr_r, curr_c = q.pop(0)
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != 0 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            cells.append((nr, nc))
                            q.append((nr, nc))

                # Sort and get bounding box
                cells.sort()
                rmin, rmax = [r for r, c in cells], [r for r, c in cells]
                cmin, cmax = [c for r, c in cells], [c for r, c in cells]
                rmin, rmax = min(rmin), max(rmax)
                cmin, cmax = min(cmin), max(cmax)

                # Extract subgrid (7-wide centered on core 4-6-4)
                return (rmin, rmax, cmin, cmax, cells)

    return components

